import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
    }

    static long evaluate(long slope, long intercept, long x) {
        return slope * x + intercept;
    }

    static boolean productGreaterOrEqual(long a, long b, long c, long d) {
        long high1 = Math.multiplyHigh(a, b);
        long low1 = a * b;
        long high2 = Math.multiplyHigh(c, d);
        long low2 = c * d;

        if (high1 != high2) return high1 > high2;
        return Long.compareUnsigned(low1, low2) >= 0;
    }

    static boolean redundant(long m1, long b1, long m2, long b2, long m3, long b3) {
        return productGreaterOrEqual(
                b2 - b1, m2 - m3,
                b3 - b2, m1 - m2
        );
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int k = fs.nextInt();

        long[] sizes = new long[n];
        for (int i = 0; i < n; i++) sizes[i] = fs.nextInt();
        Arrays.sort(sizes);

        final long INF = Long.MAX_VALUE / 4;
        long[] prev = new long[n + 1];
        long[] cur = new long[n + 1];

        for (int groups = 1; groups <= k; groups++) {
            Arrays.fill(cur, INF);

            long[] slopes = new long[n];
            long[] intercepts = new long[n];
            int head = 0, tail = 0;
            long bestPair = INF;
            cur[0] = INF;

            for (int i = 1; i <= n; i++) {
                cur[i] = cur[i - 1];

                if (i >= 3) {
                    int aIndex = i - 3;
                    long previousCost = prev[aIndex];

                    if (previousCost < INF) {
                        long x = sizes[aIndex];
                        long slope = -2L * x;
                        long intercept = previousCost + x * x;

                        while (tail > head && slopes[tail - 1] == slope) {
                            if (intercepts[tail - 1] <= intercept) {
                                slope = Long.MIN_VALUE;
                                break;
                            }
                            tail--;
                        }

                        if (slope != Long.MIN_VALUE) {
                            while (tail - head >= 2 &&
                                    redundant(slopes[tail - 2], intercepts[tail - 2],
                                            slopes[tail - 1], intercepts[tail - 1],
                                            slope, intercept)) {
                                tail--;
                            }
                            slopes[tail] = slope;
                            intercepts[tail] = intercept;
                            tail++;
                        }
                    }

                    if (head < tail) {
                        long x = sizes[i - 2];
                        while (head + 1 < tail &&
                                evaluate(slopes[head + 1], intercepts[head + 1], x)
                                        <= evaluate(slopes[head], intercepts[head], x)) {
                            head++;
                        }
                        long pairCost = x * x + evaluate(slopes[head], intercepts[head], x);
                        if (pairCost < bestPair) bestPair = pairCost;
                    }

                    if (bestPair < cur[i]) cur[i] = bestPair;
                }
            }

            long[] temp = prev;
            prev = cur;
            cur = temp;
        }

        System.out.println(prev[n]);
    }
}
